_value_key=None
def install_value_key(key):
    global _value_key
    require(_value_key is None and type(key) is bytes and len(key)==32,'Fresh private32-byte key required');_value_key=key
def initialize_private_key(root,filename="private-value-hmac-key.json"):
    require(filename in {'private-value-hmac-key.json','private-stop-post-hmac-key.json'},'Exact private key filename required')
    root=pathlib.Path(root);p=child_path(root,root/filename)
    key=os.urandom(32)
    with p.open('xb') as f:f.write(canonical({'algorithm':'HMAC-SHA256','keyHex':key.hex(),'withheld':True})+b'\n')
    p.chmod(0o400);install_value_key(key)
def projection(v):
    if isinstance(v,bytes):return {'blobHex':v.hex()}
    if isinstance(v,(tuple,list)):return [projection(x) for x in v]
    if isinstance(v,dict):return {k:projection(x) for k,x in v.items()}
    return v
def value_hash(v):
    require(type(_value_key) is bytes and len(_value_key)==32,'Private value key missing')
    return hmac.new(_value_key,canonical(projection(v)),hashlib.sha256).hexdigest()
def public_failure(e):
    if type(e) is RuntimeError and len(e.args)==1 and type(e.args[0]) is str:
        tb=e.__traceback__
        while tb is not None:
            site=(pathlib.Path(tb.tb_frame.f_code.co_filename).name,tb.tb_lineno)
            if e.args[0] in STATIC_FAILURE_SITES.get(site,()):return {'errorType':'RuntimeError','literalRequire':e.args[0]}
            tb=tb.tb_next
    return {'errorType':type(e).__name__,'errorHmacSha256':value_hash(str(e))}

def strict(raw):
    require(isinstance(raw,(str,bytes)) and len(raw)<=8*1024**2,'Bounded JSON required')
    def pairs(items):
        out={}
        for k,v in items:require(k not in out,'Duplicate JSON key');out[k]=v
        return out
    def nonfinite(_):raise RuntimeError('Nonfinite JSON refused')
    return json.loads(raw,object_pairs_hook=pairs,parse_constant=nonfinite)

